"""Read-only sheet ancestry audit for the actual inherited wall crossings."""
from pathlib import Path
from collections import Counter
import sys,json,time
import numpy as np
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from geometry_tools.common import ROOT,atomic_json,atomic_npz,digest_file
from geometry_tools.model import Mesh
from geometry_tools.spatial import BVH
WORK=ROOT/'.local-models/geometry-workbench/circulatory-completion/male-cystic-blood-donor-v1';AUDIT=WORK/'fixed-artery-biliary-audit-v32'
LIVER=ROOT/'.local-models/geometry-workbench/liver-completion'

def main():
    began=time.monotonic();src=AUDIT/'stage1-localization';out=AUDIT/'stage2-tissue-classification';assert not out.exists();out.mkdir();proof=json.loads((src/'proof.json').read_text());w=np.load(src/'actual-crossing-witnesses.npz');line=np.load(src/'face-lineage.npz');duct=Mesh.load(src/'fixed-hepatic-biliary-wall.npz');artery=Mesh.load(src/'fixed-cystic-artery.npz');assert duct.geometry_sha==proof['fixedBiliaryGeometrySha256'];assert artery.geometry_sha==proof['fixedArteryGeometrySha256'];field=json.loads((LIVER/'hepatic-contained-banks-v181/biliary-evidence.json').read_text());assert field['geometrySha256']==duct.geometry_sha
    source=Mesh.load(LIVER/'packed-hepatic-biliary-v128/TA98HEPATIC_male_biliary.npz');old=json.loads((LIVER/'float32-connections-v126/biliary.json').read_text());assert source.geometry_sha==old['quality']['geometry_sha256'];parents=np.load(LIVER/'hepatic-contained-banks-v181/biliary-parents.npz')['parent'];assert len(parents)==len(duct.faces) and parents.max()<len(source.faces);current_faces=np.unique(w['pairs'][:,1]);source_faces=parents[current_faces];unique_source=np.unique(source_faces);points=source.triangles[unique_source].mean(1);outer=Mesh.load(LIVER/'rebuilt-biliary-v107/outer.npz');inner=Mesh.load(LIVER/'rebuilt-biliary-v107/fluid.npz');oh,oe=BVH(outer).closest_points(points);ih,ie=BVH(inner).closest_points(points);distance=np.c_[oh['distance_m'],ih['distance_m']];classification=np.where(distance[:,0]<distance[:,1],'outer','inner');minimum=distance.min(1);margin=abs(distance[:,0]-distance[:,1]);uncertain=(minimum>1e-7)|(margin<1e-7);classification[uncertain]='unclassified';lookup=dict(zip(unique_source,classification));current_sheet=np.array([lookup[int(parents[i])]for i in current_faces]);full_sheet=np.full(len(duct.faces),'not-audited',object);full_sheet[current_faces]=current_sheet
    rows=[];pair_classes=[]
    for i,j in w['pairs']:
        arterial={1:'outer',3:'inner',6:'shared-annulus'}.get(int(line['artery_source_sheets'][i]),'unclassified');pair_classes.append((arterial,str(full_sheet[j]),str(line['biliary_owner_ids'][j]),int(line['artery_source_stations'][i])))
    for key,n in sorted(Counter(pair_classes).items()):rows.append(dict(arterySheet=key[0],biliarySheet=key[1],biliaryRegion=key[2],arterySourceStationInterval=key[3],crossingFacePairs=n))
    # Distinct packed bank/source identities plus strict proper intersections
    # rule out an alias-only count or coincident regional index view duplication.
    keys=lambda m,ids:{tuple(sorted(tuple(float(x)for x in p)for p in tri))for tri in m.triangles[ids]}
    same_triangles=keys(artery,np.unique(w['pairs'][:,0]))&keys(duct,current_faces)
    result=dict(schema='inherited-cystic-artery-biliary-wall-ancestry/v33',stage1EvidenceSha256=digest_file(src/'proof.json'),fixedArteryGeometrySha256=artery.geometry_sha,fixedBiliaryGeometrySha256=duct.geometry_sha,biliaryCurrentGeometryMatchesNativeDeformationEvidence=True,biliarySourceGeometrySha256=source.geometry_sha,biliarySourceParentMapSha256=digest_file(LIVER/'hepatic-contained-banks-v181/biliary-parents.npz'),biliaryInnerSourceSha256=digest_file(LIVER/'rebuilt-biliary-v107/fluid.npz'),biliaryOuterSourceSha256=digest_file(LIVER/'rebuilt-biliary-v107/outer.npz'),biliarySourceFaceClassificationMethod='Actual deformed-face ancestry -> packed original wall face centroid -> exact nearest original outer or fluid boundary triangles; cap/ambiguous faces remain unclassified',sourceBoundaryClassificationTolerance_m=1e-7,maximumClassifiedSourceBoundaryResidual_m=float(minimum[~uncertain].max()),minimumClassifiedOtherBoundaryMargin_m=float(margin[~uncertain].min()),classifiedCurrentBiliaryFaces=Counter(map(str,current_sheet)),unclassifiedSourceFaces=unique_source[uncertain].tolist(),identicalCrossMeshTriangles=len(same_triangles),strictProperCrossingsNotAlias=True,innerBiliaryBoundaryCrossed=any(r['biliarySheet']=='inner'for r in rows),innerArterialAndBiliaryBoundariesCross=any(r['arterySheet']=='inner'and r['biliarySheet']=='inner'for r in rows),actualFiniteWallBoundaryCrossings=True,externalExclusionClassifiersUsed=False,sourceHostAliasesDoubleCounted=False,pairClassifications=rows,notAnatomicallyAccepted=True,geometryModified=False,installed=False,elapsedSeconds=time.monotonic()-began);atomic_npz(out/'sheet-ancestry.npz',current_biliary_faces=current_faces,source_biliary_faces=source_faces,unique_source_faces=unique_source,source_boundary_distances_m=distance,source_sheet=classification,current_sheet=np.array(current_sheet,str));atomic_json(out/'proof.json',result);print(json.dumps(dict(stage2=str(out),classifiedCurrentBiliaryFaces=dict(result['classifiedCurrentBiliaryFaces']),unclassified=len(result['unclassifiedSourceFaces']),innerVsInnerPairs=sum(r['crossingFacePairs']for r in rows if r['arterySheet']=='inner'and r['biliarySheet']=='inner'),sameMeshTriangles=len(same_triangles),maximumSourceResidual_m=result['maximumClassifiedSourceBoundaryResidual_m'],elapsedSeconds=result['elapsedSeconds'])))
if __name__=='__main__':main()
